import React, { useState } from 'react';
import 'estilos/LoginRegister.css';

const LoginRegister = () => {
  const [isLogin, setIsLogin] = useState(false);
  const [formData, setFormData] = useState({
    matricula: '',
    correo: '',
    password: '',
    confirmPassword: ''
  });
  const [errors, setErrors] = useState({});
  const [isBlocked, setIsBlocked] = useState(false);
  const [showTemporaryBlock, setShowTemporaryBlock] = useState(false);
  const [showPermanentBlock, setShowPermanentBlock] = useState(false);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value
    });
    // Limpiar errores cuando el usuario escribe
    if (errors[name]) {
      setErrors({
        ...errors,
        [name]: ''
      });
    }
  };

  const validateEmail = (email) => {
    const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return re.test(email);
  };

  const validatePassword = (password) => {
    const hasUpperCase = /[A-Z]/.test(password);
    const hasNumber = /\d/.test(password);
    const hasSpecialChar = /[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]/.test(password);
    return password.length >= 8 && hasUpperCase && hasNumber && hasSpecialChar;
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const newErrors = {};

    // Validaciones
    if (!formData.matricula) {
      newErrors.matricula = 'La matrícula es requerida';
    }

    if (!formData.correo) {
      newErrors.correo = 'El correo es requerido';
    } else if (!validateEmail(formData.correo)) {
      newErrors.correo = 'Formato de correo electrónico no válido';
    }

    if (!formData.password) {
      newErrors.password = 'La contraseña es requerida';
    } else if (!validatePassword(formData.password)) {
      newErrors.password = 'La contraseña no cumple los requisitos';
    }

    if (!formData.confirmPassword) {
      newErrors.confirmPassword = 'Confirma tu contraseña';
    } else if (formData.password !== formData.confirmPassword) {
      newErrors.confirmPassword = 'Las contraseñas no coinciden';
    }

    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }

    // Simulaciones de bloqueo
    if (formData.matricula === '12345') {
      setShowTemporaryBlock(true);
      setTimeout(() => setShowTemporaryBlock(false), 5000);
      return;
    }

    if (formData.matricula === '99999') {
      setShowPermanentBlock(true);
      setTimeout(() => setShowPermanentBlock(false), 5000);
      return;
    }

    // Registro exitoso
    console.log('Datos enviados:', formData);
    alert('Registro exitoso');
  };

  const handleRecoverPassword = () => {
    alert('Funcionalidad de recuperación de contraseña');
  };

  return (
    <div className="auth-container">
      <div className="auth-card">
        {/* Header */}
        <div className="auth-header">
          <h1 className="main-title">BIBLIOTECA YEAK8</h1>
          <div className="subtitle">
            <div className="divider"></div>
            <span>REGISTRO EXCLUSIVO ESTUDIANTES</span>
            <div className="divider"></div>
          </div>
        </div>

        {/* Alertas de bloqueo */}
        {showTemporaryBlock && (
          <div className="alert alert-warning">
            <strong>Su cuenta ha sido bloqueada temporalmente.</strong>
            <span>Intente de nuevo en 5 minutos.</span>
          </div>
        )}

        {showPermanentBlock && (
          <div className="alert alert-error permanent">
            <strong>CUENTA BLOQUEADA PERMANENTEMENTE.</strong>
            <span>CONTACTE A SOPORTE</span>
          </div>
        )}

        {/* Formulario */}
        <form onSubmit={handleSubmit} className="auth-form">
          {/* Matrícula */}
          <div className="form-section">
            <label className="section-label">Matrícula</label>
            <input
              type="text"
              name="matricula"
              value={formData.matricula}
              onChange={handleChange}
              className={errors.matricula ? 'error' : ''}
              placeholder="Ingrese su matrícula"
            />
          </div>

          {/* Correo Electrónico */}
          <div className="form-section">
            <label className="section-label">Correo Electrónico</label>
            <input
              type="email"
              name="correo"
              value={formData.correo}
              onChange={handleChange}
              className={errors.correo ? 'error' : ''}
              placeholder="correo@ejemplo.com"
            />
            {errors.correo && (
              <div className="error-message">
                {errors.correo}
              </div>
            )}
          </div>

          {/* Contraseña */}
          <div className="form-section">
            <label className="section-label">
              Contraseña
              <span className="requirement">(8+ caracteres, 1 Mayús, 1 Num, 1 Signo)</span>
            </label>
            <input
              type="password"
              name="password"
              value={formData.password}
              onChange={handleChange}
              className={errors.password ? 'error' : ''}
              placeholder="Ingrese su contraseña"
            />
          </div>

          {/* Confirmar Contraseña */}
          <div className="form-section">
            <label className="section-label">Confirmar Contraseña</label>
            <input
              type="password"
              name="confirmPassword"
              value={formData.confirmPassword}
              onChange={handleChange}
              className={errors.confirmPassword ? 'error' : ''}
              placeholder="Confirme su contraseña"
            />
            {errors.confirmPassword && (
              <div className="error-message">
                {errors.confirmPassword}
              </div>
            )}
          </div>

          {/* Botones */}
          <div className="buttons-container">
            <button type="submit" className="btn-primary">
              REGISTRAR
            </button>
            <button type="button" className="btn-secondary" onClick={handleRecoverPassword}>
              RECUPERAR CONTRASEÑA
            </button>
          </div>
        </form>

        {/* Footer */}
        <div className="auth-footer">
          <p>¿Ya tienes cuenta? <span className="link">Iniciar Sesión</span></p>
        </div>
      </div>
    </div>
  );
};

export default LoginRegister;
